extern int Live2DCubism4_Initialize_PF( void )
{
	// DLL ??Åg???????
	if( Live2DCubism4_DLL_Load() < 0 )
	{
		return -1 ;
	}

	// ?R?Åg?X?^?Åg?g?o?b?t?@???g?p?????????????????Z?b?g
	LIVE2DSYS.EnableConstantBuffer = GRAWIN.Setting.UseGraphicsAPI == GRAPHICS_API_DIRECT3D11_WIN32 ? TRUE : FALSE ;

	// ?V?F?[?_?[?I?u?W?F?N?g?t?@?C???c?w?`?????k?????f?[?^??ÅÒ?Åg?????
	switch( GRAWIN.Setting.UseGraphicsAPI )
	{
#ifndef DX_NON_DIRECT3D11
	case GRAPHICS_API_DIRECT3D11_WIN32 :
		if( Live2DCubism4_SetupShaderCode( &DxShaderCodeBin_Live2D_Cubism4_D3D11Convert, DxShaderCodeBin_Live2D_Cubism4_D3D11 ) < 0 )
		{
			return -1 ;
		}
		break ;
#endif // DX_NON_DIRECT3D11

#ifndef DX_NON_DIRECT3D9
	case GRAPHICS_API_DIRECT3D9_WIN32 :
		if( Live2DCubism4_SetupShaderCode( &DxShaderCodeBin_Live2D_Cubism4_D3D9Convert, DxShaderCodeBin_Live2D_Cubism4_D3D9 ) < 0 )
		{
			return -1 ;
		}
		break ;
#endif // DX_NON_DIRECT3D9

	default :
		return -1 ;
	}

	return 0 ;
}

