extern int Live2DCubism4_SetupShader_PF( int ConstantBufferHandle, D_CubismConstantBufferDxLib *ConstantBuffer, D_ShaderNames VertexShader, D_ShaderNames PixelShader )
{
	D_CubismShader_DxLib* shaderManager = D_CubismRenderer_DxLib::GetShaderManager();

	if( shaderManager == NULL )
	{
		return -1 ;
	}

	if( LIVE2DSYS.UserShader[ Live2D_VertexShaderToDxLibShader_Table[ VertexShader ] ] > 0 )
	{
		NS_SetUseVertexShader( LIVE2DSYS.UserShader[ Live2D_VertexShaderToDxLibShader_Table[ VertexShader ] ] ) ;
	}
	else
	{
		NS_SetUseVertexShader( shaderManager->GetVertexShader( VertexShader ) ) ;
	}

	if( LIVE2DSYS.UserShader[ Live2D_PixelShaderToDxLibShader_Table[ PixelShader ] ] > 0 )
	{
		NS_SetUsePixelShader( LIVE2DSYS.UserShader[ Live2D_PixelShaderToDxLibShader_Table[ PixelShader ] ] ) ;
	}
	else
	{
		NS_SetUsePixelShader( shaderManager->GetPixelShader( PixelShader ) ) ;
	}

	if( LIVE2DSYS.EnableConstantBuffer )
	{
		// Update 
		NS_UpdateShaderConstantBuffer( ConstantBufferHandle ) ;

		// ?Z?b?g???? 
		NS_SetShaderConstantBuffer( ConstantBufferHandle, DX_SHADERTYPE_VERTEX, 0 ) ;
		NS_SetShaderConstantBuffer( ConstantBufferHandle, DX_SHADERTYPE_PIXEL, 0 ) ;
	}
	else
	{
		NS_SetVSConstFMtx( 0, ConstantBuffer->projectMatrix ) ;
		NS_SetVSConstFMtx( 4, ConstantBuffer->clipMatrix ) ;
		NS_SetPSConstF(  8, *( ( FLOAT4 * )&ConstantBuffer->baseColor ) ) ;
		NS_SetPSConstF(  9, *( ( FLOAT4 * )&ConstantBuffer->multiplyColor ) ) ;
		NS_SetPSConstF( 10, *( ( FLOAT4 * )&ConstantBuffer->screenColor ) ) ;
		NS_SetPSConstF( 11, *( ( FLOAT4 * )&ConstantBuffer->channelFlag ) ) ;
	}

	return 0 ;
}

// Live2D Cubism4 ???`ÅÒ?????????????????????ÅeÅ˜???Åh
extern int Live2DCubism4_DrawAfter_PF( void )
{
	if( LIVE2DSYS.EnableConstantBuffer == FALSE )
	{
		NS_ResetVSConstF( 0, 8 ) ;
		NS_ResetPSConstF( 8, 2 ) ;
	}

	return 0 ;
}

bool D_CubismShader_DxLib::LoadShaderProgram(bool isPs, int assign, const char* entryPoint)
{
    bool bRet = false;
	char FilePath[ 1024 ];

    int vertexShader = -1;
    int pixelShader = -1;

    do
    {
		CL_strcpy( DX_CHARCODEFORMAT_ASCII, FilePath, entryPoint );
		if( isPs )
		{
			CL_strcat( DX_CHARCODEFORMAT_ASCII, FilePath, ".pso" ) ;
			pixelShader = Live2DCubism4_LoadShaderCode( FilePath, DX_SHADERTYPE_PIXEL ) ;
			if( pixelShader < 0 )
			{
				// CubismLogWarning("Fail Create Shader");
				break;
			}
            _shaderSetsPS[assign] = pixelShader;
		}
		else
		{
			CL_strcat( DX_CHARCODEFORMAT_ASCII, FilePath, ".vso" ) ;
			vertexShader = Live2DCubism4_LoadShaderCode( FilePath, DX_SHADERTYPE_VERTEX ) ;
			if( vertexShader < 0 )
			{
				// CubismLogWarning("Fail Create Shader");
				break;
			}
            _shaderSetsVS[assign] = vertexShader;
		}
        // ???ÅÄ 
        bRet = true;
    } while (0);

    return bRet;
}

